1	//! The MHPCO price list: what each insurable item costs to cover, before any
2	//! risk assessment or customer standing is taken into account.
3	//!
4	//! This is the catalog side of the office's knowledge. It changes when the
5	//! MHPCO revises its prices or its building-block offer, independently of the
6	//! underwriting rules that surcharge and discount a policy.
7	
8	use std::collections::BTreeMap;
9	
10	use crate::Item;
11	
12	const COMPONENT_BLOCK_SIZE: usize = 3;
13	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
14	
15	/// One entry in the MHPCO price list: what an item of this kind costs to
16	/// cover, and what the office insures it for. The two travel together because
17	/// they are one row of the list -- the office revises a price-list entry as a
18	/// whole -- and because the kind decides how the item is priced in a policy.
19	struct Listing {
20	    base_premium: f64,
21	    insurance_value: i64,
22	    /// Components are the small insurable parts the MHPCO lists apart from
23	    /// main items: they are priced per component and may form building blocks.
24	    is_component: bool,
25	}
26	
27	const SWORD: Listing = Listing {
28	    base_premium: 100.0,
29	    insurance_value: 1000,
30	    is_component: false,
31	};
32	const AMULET: Listing = Listing {
33	    base_premium: 60.0,
34	    insurance_value: 600,
35	    is_component: false,
36	};
37	const STAFF: Listing = Listing {
38	    base_premium: 80.0,
39	    insurance_value: 800,
40	    is_component: false,
41	};
42	const POTION: Listing = Listing {
43	    base_premium: 40.0,
44	    insurance_value: 400,
45	    is_component: false,
46	};
47	const COMPONENT: Listing = Listing {
48	    base_premium: 25.0,
49	    insurance_value: 250,
50	    is_component: true,
51	};
52	
53	/// The item's entry in the MHPCO price list, if the office lists its type at
54	/// all. An item type the list does not name is not insurable.
55	fn listed(item: &Item) -> Option<&'static Listing> {
56	    match item.item_type.as_str() {
57	        "sword" => Some(&SWORD),
58	        "amulet" => Some(&AMULET),
59	        "staff" => Some(&STAFF),
60	        "potion" => Some(&POTION),
61	        "rune" | "moonstone" => Some(&COMPONENT),
62	        _ => None,
63	    }
64	}
65	
66	/// Whether the MHPCO lists this item type at all.
67	pub(crate) fn is_listed(item: &Item) -> bool {
68	    listed(item).is_some()
69	}
70	
71	/// The item's entry in the MHPCO price list. Only called for items the office
72	/// has already accepted as listed, so an unlisted type cannot reach here.
73	fn listing_for(item: &Item) -> &'static Listing {
74	    listed(item).unwrap_or(&SWORD)
75	}
76	
77	fn is_component(item: &Item) -> bool {
78	    listing_for(item).is_component
79	}
80	
81	/// A building block of alike components is offered at a special base premium.
82	fn component_group_base_premium(count: usize) -> f64 {
83	    if count == COMPONENT_BLOCK_SIZE {
84	        COMPONENT_BLOCK_BASE_PREMIUM
85	    } else {
86	        count as f64 * COMPONENT.base_premium
87	    }
88	}
89	
90	/// Components are alike when they are of the very same type: the MHPCO reads
91	/// "3 alike components" strictly, so runes and moonstones never share a block.
92	fn alike_component_kind(item: &Item) -> &str {
93	    item.item_type.as_str()
94	}
95	
96	/// The base premium of all components in a policy: components of the same kind
97	/// are counted together so that their building block can apply.
98	fn components_base_premium(items: &[Item]) -> f64 {
99	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
100	    for item in items.iter().filter(|item| is_component(item)) {
101	        *counts.entry(alike_component_kind(item)).or_default() += 1;
102	    }
103	    counts.into_values().map(component_group_base_premium).sum()
104	}
105	
106	/// The base premium of all main items in a policy, straight from the price list.
107	fn main_items_base_premium(items: &[Item]) -> f64 {
108	    items
109	        .iter()
110	        .filter(|item| !is_component(item))
111	        .map(|item| listing_for(item).base_premium)
112	        .sum()
113	}
114	
115	/// The policy base premium: the sum of the base premiums of all insured items.
116	pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
117	    main_items_base_premium(items) + components_base_premium(items)
118	}
119	
120	/// The base premium an item-specific modifier is measured against: the item's
121	/// own listed price, which for a component is the per-component premium.
122	pub(crate) fn item_base_premium(item: &Item) -> f64 {
123	    listing_for(item).base_premium
124	}
125	
126	/// The insurance sum of a policy: the sum of its items' insurance values.
127	/// Unlike the premium, the insurance sum knows nothing of building blocks --
128	/// three alike components are insured for three times a component's value.
129	pub(crate) fn insurance_sum(items: &[Item]) -> i64 {
130	    items
131	        .iter()
132	        .map(|item| listing_for(item).insurance_value)
133	        .sum()
134	}
